        boneProjectionSampleAt(uv + texel * vec2(1.7, 1.7)) +
        boneProjectionSampleAt(uv + texel * vec2(-1.7, 1.7)) +
        boneProjectionSampleAt(uv + texel * vec2(1.7, -1.7)) +
        boneProjectionSampleAt(uv + texel * vec2(-1.7, -1.7))
